import React from 'react';
import { useContext } from 'react';
import { GameClientContext } from '../contexts/GameClientContext';

import { useNavigate, useLocation } from 'react-router-dom';
import styled from 'styled-components';
import GameClient from '../services/GameClient';
import { useGameExit } from '../hooks/useGameExit';

const Container = styled.div`
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  padding: 20px;
  background: linear-gradient(135deg, #f5f7fa 0%, #c3cfe2 100%);
`;

const Title = styled.h2`
  font-size: 32px;
  color: #1a1a1b;
  margin-bottom: 40px;
  text-align: center;
`;

const ModeGrid = styled.div`
  display: flex;
  gap: 20px;

  @media (max-width: 600px) {
  flex-direction: column;
  width: 100%;
  max-width: 300px;
  }
`;

const ModeCard = styled.div`
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  width: 200px;
  height: 160px;
  background: white;
  border: 2px solid #d3d6da;
  border-radius: 12px;
  transition: all 0.25s ease;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.05);
  text-align: center;

  &:hover {
    transform: translateY(-4px);
    box-shadow: 0 6px 12px rgba(0, 0, 0, 0.1);
    background: #f9f9f9;
  }
`

const ModeName = styled.div`
  font-size: 18px;
  font-weight: bold;
  margin-bottom: 8px;
`

const ModeButton = styled.button`
  width: 200px;
  padding: 20px;
  margin: 10px;
  font-size: 18px;
  font-weight: bold;
  background: white;
  border: 2px solid #d3d6da;
  border-radius: 8px;
  cursor: pointer;
  transition: all 0.2s;

  &:hover {
    background: #f4f4f4;
    transform: translateY(-2px);
  }
`;

const ModeDescription = styled.p`
  font-size: 14px;
  color: #666;
  text-align: center;
  margin: 0;
`;


const ModeSelection: React.FC = () => {
  const navigate = useNavigate();
  const location = useLocation();
  console.log("Location state: ", location.state);

  const { client } = useContext(GameClientContext);


  const handleSingleMode = async() => {
    console.log("ModeSelection Player: ", client?.getPlayerName());
    if (!client) {
      return;
    }
    const roomID = await client.createRoom('1');
    await client.joinGame(roomID);
    navigate('/game/single', {
       state: { 
        mode: 'single' } });
  };

  const handleMultiMode = (isSinglePlayer: boolean) => {
    console.log("ModeSelection Player: ", client?.getPlayerName());
    navigate('/rooms', {
       state: { 
        mode: 'multi' } });
  };

  useGameExit(client);

  return (
    <Container>
      <Title>Select Game Mode</Title>
      <ModeGrid>
        <ModeCard onClick={() => handleSingleMode()}>
          <ModeName>Single Player</ModeName>
          <ModeDescription>Practice by yourself</ModeDescription>
        </ModeCard>

        <ModeCard onClick={() => handleMultiMode(false)}>
          <ModeName>Multiplayer</ModeName>
          <ModeDescription>Compete with other players</ModeDescription>
        </ModeCard>
      </ModeGrid>
    </Container>
  );
};

export default ModeSelection;
